//! Every row of the `charset.*` parts of `pyre.jsonl`,
//! `pyre_unicode.jsonl` and `pyre_python.jsonl` (`gen_pyre_charset`, unit
//! pyre-4a) against `pyre::charset`: each class through
//! `optimize_charset` and `compile_class`, each membership sweep
//! regenerated here over every code point (or byte) and compared by count
//! and digest, each fuzz row regenerated by the generator's draws and
//! compared by digest. `pyre_python.jsonl` holds the classes whose answer
//! follows the release (a category beside its complement, a member past
//! the BMP under a fold) and the fuzz over every member. Rows of other
//! parts belong to other units' tests.

mod common;

use bettermemory_core::pyre::charset::{compile_class, optimize_charset, Fold, Op};
use bettermemory_core::pyre::fold::{IGNORECASE, LOCALE};
use bettermemory_core::pyre::tree::{Category, Member};
use common::parity::Ledger;
use common::{assert_count, jsonl};
use serde_json::Value;
use sha2::{Digest, Sha256};

const UNIT: &str = "pyre-4a";
const MULT: u64 = 6364136223846793005;
const INC: u64 = 1442695040888963407;

/// The generator's `Lcg`.
struct Lcg(u64);

impl Lcg {
    fn draw(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(MULT).wrapping_add(INC);
        self.0 >> 33
    }
}

const CATEGORIES: [Category; 6] = [
    Category::CATEGORY_DIGIT,
    Category::CATEGORY_NOT_DIGIT,
    Category::CATEGORY_SPACE,
    Category::CATEGORY_NOT_SPACE,
    Category::CATEGORY_WORD,
    Category::CATEGORY_NOT_WORD,
];

const POOL: [u32; 29] = [
    0, 9, 0x30, 0x41, 0x4B, 0x5A, 0x5F, 0x61, 0x6B, 0x73, 0x7A, 0xB5, 0xDF, 0xFF, 0x100, 0x130,
    0x131, 0x17F, 0x1C5, 0x3A3, 0x3C2, 0x3C3, 0x1E9E, 0x212A, 0xFEFF, 0xFFFF, 0x10000, 0x10400,
    0x10FFFF,
];
const SPANS: [u32; 7] = [0, 1, 2, 25, 255, 256, 0x1000];

fn number(v: &Value) -> u64 {
    v.as_u64().unwrap_or_else(|| panic!("a number: {v}"))
}

fn member(v: &Value) -> Member {
    let a = v.as_array().expect("a member");
    let n = |i: usize| number(&a[i]) as u32;
    match a[0].as_str().expect("a kind") {
        "negate" => Member::Negate,
        "lit" => Member::Literal(n(1)),
        "range" => Member::Range(n(1), n(2)),
        "cat" => Member::Category(
            *CATEGORIES
                .iter()
                .find(|c| format!("{c:?}") == a[1].as_str().expect("a name"))
                .expect("a category"),
        ),
        other => panic!("a member kind: {other}"),
    }
}

fn members(row: &Value) -> Vec<Member> {
    row["members"]
        .as_array()
        .expect("members")
        .iter()
        .map(member)
        .collect()
}

fn words(w: &[u32]) -> String {
    w.iter().map(|w| format!("{w:08x}")).collect()
}

/// The generator's `_op`.
fn spell(op: &Op) -> String {
    match op {
        Op::Negate => "N".into(),
        Op::Literal(c) => format!("L{c:x}"),
        Op::Range(lo, hi) => format!("R{lo:x}-{hi:x}"),
        Op::RangeUniIgnore(lo, hi) => format!("U{lo:x}-{hi:x}"),
        Op::Category(c) => format!("C{}", &format!("{c:?}")["CATEGORY_".len()..]),
        Op::Charset(w) => format!("S{}", words(w)),
        Op::BigCharset(w) if w.len() > 128 => {
            let digest = Sha256::digest(words(w).as_bytes());
            format!("B#{}:{}", w.len(), &common::hex(&digest)[..16])
        }
        Op::BigCharset(w) => format!("B{}", words(w)),
    }
}

/// The generator's `_answer`, the opcode chosen as `_compile` chooses it.
fn answer(members: &[Member], flags: u32) -> String {
    let fold = Fold::of(flags);
    let (ops, hascased) = optimize_charset(members, fold);
    let opcode = if flags & IGNORECASE != 0 && flags & LOCALE != 0 {
        "IN_LOC_IGNORE"
    } else if !hascased {
        "IN"
    } else if fold != Fold::Unicode {
        "IN_IGNORE"
    } else {
        "IN_UNI_IGNORE"
    };
    let spelled: Vec<String> = ops.iter().map(spell).collect();
    format!("{} |{opcode} h{}", spelled.join(" "), u8::from(hascased))
}

fn flags(row: &Value) -> u32 {
    number(&row["flags"]) as u32
}

fn check_class(row: &Value) {
    let m = members(row);
    let f = flags(row);
    assert_eq!(answer(&m, f), row["answer"].as_str().unwrap(), "{row}");
    match (compile_class(&m, f), row["refused"].as_str()) {
        (Err(what), Some(want)) => assert_eq!(format!("{what:?}"), want, "{row}"),
        (Ok(set), None) => {
            let (ops, hascased) = optimize_charset(&m, Fold::of(f));
            assert_eq!(set.ops, ops, "{row}");
            assert_eq!(
                format!("{:?}", set.op),
                if hascased { "InUniIgnore" } else { "In" },
                "{row}"
            );
        }
        (got, want) => panic!("{row}: compile_class gives {got:?}, the row {want:?}"),
    }
}

fn check_sweep(row: &Value, classes: &[Value]) {
    let class = classes
        .iter()
        .find(|c| {
            c["pattern"] == row["pattern"]
                && c["bytes"] == row["bytes"]
                && c["flags"] == row["flags"]
        })
        .unwrap_or_else(|| panic!("no class row for {row}"));
    let set = compile_class(&members(class), flags(row)).expect("a class the engine compiles");
    let count = number(&row["count"]) as u32;
    assert_eq!(count, if row["bytes"] == true { 256 } else { 0x110000 });
    let found: Vec<u8> = (0..count).map(|c| u8::from(set.contains(c))).collect();
    assert_eq!(
        common::hex(&Sha256::digest(&found)),
        row["sha256"].as_str().unwrap(),
        "{row}"
    );
}

/// The generator's `_drawn`.
fn drawn(seed: u64, wide: bool) -> Vec<Member> {
    let pool: Vec<u32> = POOL.into_iter().filter(|&c| wide || c <= 0xFFFF).collect();
    let categories: Vec<Category> = CATEGORIES
        .into_iter()
        .step_by(if wide { 1 } else { 2 })
        .collect();
    let top = if wide { 0x10FFFF } else { 0xFFFF };
    let mut lcg = Lcg(seed);
    let n = 1 + lcg.draw() % 6;
    (0..n)
        .map(|_| match lcg.draw() % 10 {
            0 => Member::Negate,
            1 => Member::Category(categories[(lcg.draw() % categories.len() as u64) as usize]),
            2..=5 => Member::Literal(pool[(lcg.draw() % pool.len() as u64) as usize]),
            _ => {
                let lo = pool[(lcg.draw() % pool.len() as u64) as usize];
                let span = SPANS[(lcg.draw() % SPANS.len() as u64) as usize];
                Member::Range(lo, (lo + span).min(top))
            }
        })
        .collect()
}

fn check_fuzz(row: &Value) {
    let f = flags(row);
    let seed = number(&row["seed"]);
    let count = number(&row["count"]);
    let wide = row["wide"].as_bool().expect("wide");
    assert!(count > 0);
    let mut digest = Sha256::new();
    for i in 0..count {
        digest.update(format!("{}\n", answer(&drawn(seed + i, wide), f)).as_bytes());
    }
    assert_eq!(
        common::hex(&digest.finalize()),
        row["sha256"].as_str().unwrap(),
        "fuzz {f}"
    );
}

/// The rows of this unit in `name`, checked against the header's count.
fn unit_rows(name: &str) -> Vec<Value> {
    let mut lines = jsonl(name);
    let header = lines.remove(0);
    assert_eq!(header["part"], "header", "{name}");
    let mine: Vec<Value> = lines
        .into_iter()
        .filter(|r| {
            r["part"]
                .as_str()
                .is_some_and(|p| p.starts_with("charset."))
        })
        .collect();
    assert_eq!(
        number(&header["rows"][UNIT]) as usize,
        mine.len(),
        "{name}: rows of {UNIT}"
    );
    mine
}

fn classes() -> Vec<Value> {
    let mut all = unit_rows("pyre.jsonl");
    all.extend(unit_rows("pyre_unicode.jsonl"));
    all.extend(unit_rows("pyre_python.jsonl"));
    all.retain(|r| r["part"] == "charset.class");
    all
}

fn check(row: &Value, classes: &[Value]) {
    match row["part"].as_str().unwrap() {
        "charset.class" => check_class(row),
        "charset.sweep" => check_sweep(row, classes),
        "charset.fuzz" => check_fuzz(row),
        other => panic!("unit {UNIT} has no part {other}"),
    }
}

#[test]
fn pyre_charset_every_row() {
    let rows = unit_rows("pyre.jsonl");
    let classes = classes();
    let mut checked = 0;
    for row in &rows {
        check(row, &classes);
        checked += 1;
    }
    assert_count("pyre.jsonl charset parts", checked, rows.len());
}

#[test]
fn pyre_charset_unicode_every_row() {
    let name = "pyre_unicode.jsonl";
    let rows = unit_rows(name);
    let classes = classes();
    let mut ledger = Ledger::new("pyre_charset_unicode_every_row", name);
    for row in &rows {
        ledger.case(format!("{} {}", row["part"], row["pattern"]), || {
            check(row, &classes)
        });
    }
    ledger.finish(rows.len());
}

#[test]
fn pyre_charset_python_every_row() {
    let name = "pyre_python.jsonl";
    let rows = unit_rows(name);
    let classes = classes();
    let mut ledger = Ledger::new("pyre_charset_python_every_row", name);
    for row in &rows {
        ledger.case(format!("{} {}", row["part"], row["pattern"]), || {
            check(row, &classes)
        });
    }
    ledger.finish(rows.len());
}
